import{_ as i,a as e,c as a,ac as t}from"./chunks/framework.BSuaGltH.js";const o=JSON.parse('{"title":"etcd revision、事务与配置 CAS","description":"区分全局 revision、键 version 与 mod_revision，以并发竞争解释比较交换。","frontmatter":{"title":"etcd revision、事务与配置 CAS","description":"区分全局 revision、键 version 与 mod_revision，以并发竞争解释比较交换。","showdocs":{"topics":[{"id":"etcd","title":"etcd","link":"/topics/etcd/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"etcd v3.6实践课程","summary":"区分全局 revision、键 version 与 mod_revision，以并发竞争解释比较交换。","status":"active","related":[{"title":"完整 etcd 配置 CAS 与短租约注册程序","link":"/middleware/service-discovery/etcd/plus/practice/application","kind":"完整实践","scope":"general","audience":"general"},{"title":"etcd lease、watch 与历史压缩","link":"/middleware/service-discovery/etcd/plus/subjects/lease-watch","kind":"知识专题","scope":"general","audience":"general"},{"title":"etcd v3：从键值到一致性边界","link":"/middleware/service-discovery/etcd/base/basic/start","kind":"知识专题","scope":"general","audience":"general"},{"title":"etcd：快照、恢复与 Watch 自检","link":"/middleware/service-discovery/etcd/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"etcd v3：从键值到一致性边界","link":"/middleware/service-discovery/etcd/base/basic/start"},"next":{"text":"etcd lease、watch 与历史压缩","link":"/middleware/service-discovery/etcd/plus/subjects/lease-watch"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"etcd v3：从键值到一致性边界","link":"/middleware/service-discovery/etcd/base/basic/start"},"next":{"text":"etcd lease、watch 与历史压缩","link":"/middleware/service-discovery/etcd/plus/subjects/lease-watch"}},"headers":[],"relativePath":"middleware/service-discovery/etcd/base/advanced/transactions.md","filePath":"middleware/service-discovery/etcd/base/advanced/transactions.md"}'),n={name:"middleware/service-discovery/etcd/base/advanced/transactions.md"};function l(h,s,r,d,p,c){return e(),a("div",null,[...s[0]||(s[0]=[t(`<blockquote><p>本轮为理论笔记与静态审读，示例、安装命令和验收器均未执行。下文命令用于解释步骤，预期结果不代表本轮实测；“历史验收”仅指此前批次记录。阅读和书面练习不需要启动服务。</p></blockquote><h1 id="etcd-revision、事务与配置-cas" tabindex="-1">etcd revision、事务与配置 CAS <a class="header-anchor" href="#etcd-revision、事务与配置-cas" aria-label="Permalink to &quot;etcd revision、事务与配置 CAS&quot;">​</a></h1><h2 id="revision" tabindex="-1">三种版本号 <a class="header-anchor" href="#revision" aria-label="Permalink to &quot;三种版本号 {#revision}&quot;">​</a></h2><p>前置：已启动<a href="/middleware/service-discovery/etcd/base/basic/start#environment">实验节点</a>，会读取 JSON。etcd 的 revision 是全局逻辑时钟：一次修改事务统一推进一次 revision；同一事务中多个键的变更可以具有相同 revision。键的 version 是该键自创建以来的修改次数，删除重建后重新计数。create_revision 标记创建时刻，mod_revision 标记最近修改时刻；三者不能混用。</p><div class="language-powershell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker exec showdocs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m4b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etcd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main etcdctl put </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">course</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config initial</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker exec showdocs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m4b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etcd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main etcdctl get </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">course</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w json</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker exec showdocs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m4b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etcd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main etcdctl put </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">course</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config changed</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">docker exec showdocs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m4b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etcd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main etcdctl get </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">course</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">config </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w json</span></span></code></pre></div><p>第二次读时 version 增加，create_revision 不变，mod_revision 增加；header.revision 还可能被别的键推进。不要把 header.revision 作为这个键最近修改的版本。用 <code>get --rev=N</code> 可以读某个历史状态，前提是历史还没有压缩。</p><h2 id="cas" tabindex="-1">原子比较交换 <a class="header-anchor" href="#cas" aria-label="Permalink to &quot;原子比较交换 {#cas}&quot;">​</a></h2><p>CAS 是 compare-and-swap：比较键的 mod_revision 等于读取时记录的值，成立才写新值。比较与写入作为一次服务端事务执行，两个读到相同版本的写者最多一个成功。修改值即使后来恢复到原字符串，mod_revision 也已经变化，因此比只比较字符串更能检测中间修改。</p><p>etcdctl txn 输入依次是比较、成功分支、失败分支，分支之间以空行分隔。不存在的键 mod_revision 为 0，可用于“仅在未创建时写入”。失败分支读回当前值，帮助提示用户冲突；不能把冲突当作自动覆盖许可。</p><div class="language-text vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mod(&quot;/course/config&quot;) = &quot;7&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>put &quot;/course/config&quot; &quot;new-value&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>get &quot;/course/config&quot;</span></span></code></pre></div><p>上面的文本是事务输入内容，不是独立 Shell 命令。若要形成完整调用，在仓库根目录创建 UTF-8 文本 <code>examples/etcd/cas.txt</code>，保存该文本并保留分支之间的空行；以下 PowerShell 管道把它送入容器内的 etcdctl 标准输入（本轮不执行）：</p><div class="language-powershell vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Get-Content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Raw </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Encoding utf8 examples</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etcd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cas.txt </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">|</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> docker exec </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i showdocs</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m4b</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">etcd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">main etcdctl txn </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">w json</span></span></code></pre></div><p>这里的 7 是演示，必须替换为真实 mod_revision。返回 FAILURE 表示比较未满足，不是事务只执行了一半；JSON 的 succeeded 字段更适合程序判定。成功和失败分支各自也是原子的。不要在同一事务内重复修改同一个键，也不要以多条独立 put 代替多键原子提交。</p><h2 id="race" tabindex="-1">竞争验收与业务处理 <a class="header-anchor" href="#race" aria-label="Permalink to &quot;竞争验收与业务处理 {#race}&quot;">​</a></h2><p>并发更新必须将冲突作为正常业务分支。完整程序在<a href="/middleware/service-discovery/etcd/plus/practice/application#source">配置应用</a>中。分别运行 get，拿到 revision 后，让两个终端对同一 revision 执行 cas。预期一个退出 0、一个退出 2，最终值是其中一个写者的值。项目验证器使用两个真正并行的子进程发起竞争，并检查退出码集合是 <code>[0,2]</code>，不会靠顺序写入伪造竞争结果。</p><p>业务可以在冲突后重新读取配置、展示差异并由用户合并，或在操作确实可重算时有限重试。把整个旧配置盲目重发会丢失其他客户端的修改。事务只协调 etcd 内部状态，不会把发邮件、调用外部 API 或写本地文件也变成原子操作；外部副作用需要幂等协议与自己的失败恢复设计。</p><h2 id="exercise" tabindex="-1">练习与参考解法 <a class="header-anchor" href="#exercise" aria-label="Permalink to &quot;练习与参考解法 {#exercise}&quot;">​</a></h2><p>题目：A 读到 blue，B 改为 red 又改回 blue，A 比较 value=blue 可以发现 B 的修改吗？比较哪个字段合适？</p><p>提示：分别记录 blue→red→blue 时 value 与 mod_revision 是否回到初值。</p><details><summary>参考答案与边界</summary><p>只比较 value 无法发现这段修改；比较先前读到的 mod_revision 会失败。若业务只关心当前值是否 blue，值比较也可能是正确合同，关键是先明确“是否有中间修改”是否属于业务冲突。不要把所有值比较都说成错误。</p></details><p>资料：<a href="https://etcd.io/docs/v3.6/learning/api/" target="_blank" rel="noopener noreferrer">官方 API 机制</a>、<a href="https://github.com/etcd-io/etcd/blob/v3.6.8/etcdctl/README.md" target="_blank" rel="noopener noreferrer">etcdctl 事务输入格式</a>。</p>`,21)])])}const E=i(n,[["render",l]]);export{o as __pageData,E as default};
